"""Exact all-six completion + externally retained tool-return protocol, no anti-forgery."""
import json,hashlib,math
from pathlib import Path
from common import *
ROSTER=list(range(2,8))
def exact_roster(values):need(values==ROSTER and all(type(i)is int for i in values),'exact ordered all-six completion roster required')
def validate(out,receipt):
 out=Path(out);exact_roster(receipt['parent_roster']);need(receipt['phase']=='dynamic-six'and receipt['contract_sha256']==EXPECTED_CONTRACT,'batch completion identity differs');need(set(receipt['comparison_artifacts'])=={'comparison-execution.json','../all-six-comparison.json'},'exact all-six comparison artifacts required')
 for name,expected in receipt['comparison_artifacts'].items():need(pin(out/name)==expected,'batch comparison artifact changed')
 auth=json.loads((out/'authorization.json').read_text());exact_roster(auth['parent_roster']);need(auth['contract_sha256']==EXPECTED_CONTRACT,'authorization source differs');snapshot=reviewed_sources(auth['review'],auth['review_digest'],EXPECTED_CONTRACT);resource=auth['resource_receipt'];exact_roster(resource['parent_roster']);need(resource['phase']=='dynamic-six'and resource['contract_sha256']==EXPECTED_CONTRACT and digest(resource)==auth['resources_digest'],'batch resource identity differs')
 execution=json.loads((out/'comparison-execution.json').read_text());need(set(execution)=={'schema','phase','parent_roster','contract_sha256','review_digest','source_sha256','scope'}and execution['schema']=='SixParentComparisonExecutionV1'and execution['phase']=='dynamic-six'and execution['contract_sha256']==EXPECTED_CONTRACT,'comparison execution schema differs');exact_roster(execution['parent_roster']);need(execution['review_digest']==auth['review_digest']and execution['source_sha256']=={n:hashlib.sha256(v).hexdigest()for n,v in snapshot.items()},'reviewed comparison source differs')
 comparison=json.loads((out/'../all-six-comparison.json').read_text());need(set(comparison)=={'schema','status','parent_roster','parents','call_count','outer_masses','normalizers_posteriors','scope'}and comparison['schema']=='AllSixDynamicWitnessComparisonV1'and comparison['status']=='all_six_three_saved_points_and_exact_owned_FD_calls_verified'and comparison['call_count']==42 and comparison['outer_masses']==[.125]*8 and comparison['normalizers_posteriors']=='unverified','all-six comparison schema/status differs');exact_roster(comparison['parent_roster']);exact_roster([row['ordinal']for row in comparison['parents']]);c=read_contract()
 for row in comparison['parents']:
  need(set(row)=={'ordinal','parent_identity','errors','FD_variables','calls','conditional_normalization'}and row['calls']==7 and row['parent_identity']==c['remaining_parents'][str(row['ordinal'])]['parent_identity']and row['FD_variables']==c['finite_difference_variables']and row['conditional_normalization']=='unverified'and len(row['errors'])==3,'complete per-parent witness comparison required')
  for errors in row['errors']:need(set(errors)=={'logp','poll_logp','factors','rates','physical'}and all(type(x)in [int,float]and math.isfinite(x)and x>=0 for x in errors.values()),'finite full numerical comparison errors required')
 result=json.loads((out/'result.json').read_text());need(result['schema']=='SixParentDynamicWitnessResultV1'and result['status']=='all_six_owned_calls_persisted_not_yet_compared'and result['phase']=='dynamic-six'and result['contract_sha256']==EXPECTED_CONTRACT,'whole batch result incomplete');exact_roster(result['parent_roster']);exact_roster([row['ordinal']for row in result['parents']]);terminal=json.loads((out/'terminal.json').read_text());need(terminal['arm']=='dynamic-six'and terminal['returncode']==0 and terminal['reason']is None,'failed/partial child cannot complete batch')

def response(out):
 out=Path(out);r=json.loads((out/'controller-success.json').read_text());return dict(schema='SixParentControllerReturnV1',status='completed',phase='dynamic-six',parent_roster=ROSTER,contract_sha256=EXPECTED_CONTRACT,controller_success=pin(out/'controller-success.json'),comparisons=r['comparison_artifacts'])
def publish_success(out,comparisons):
 out=Path(out);r=dict(schema='SixParentControllerSuccessV1',status='all_six_successfully_reaped_and_compared',phase='dynamic-six',parent_roster=ROSTER,contract_sha256=EXPECTED_CONTRACT,result=pin(out/'result.json'),terminal=pin(out/'terminal.json'),authorization=pin(out/'authorization.json'),comparison_artifacts=comparisons);validate(out,r);atomic_json(out/'controller-success.json',r);return response(out)
def completed(out,tool_path,tool_sha):
 out=Path(out);tool_path=Path(tool_path);need(sha(tool_path)==tool_sha,'retained batch tool-return changed');retained=json.loads(tool_path.read_text());need(retained['schema']=='RetainedSelectedStageToolReturnV1','retained successful tool-return schema required');tool=retained['write_stdin_return'];need(type(tool['exit_code'])is int and tool['exit_code']==0 and json.loads(tool['output'])==response(out),'retained full successful batch response mismatch');r=json.loads((out/'controller-success.json').read_text());need(set(r)=={'schema','status','phase','parent_roster','contract_sha256','result','terminal','authorization','comparison_artifacts'}and r['schema']=='SixParentControllerSuccessV1'and r['status']=='all_six_successfully_reaped_and_compared','exact whole-batch success schema required')
 for name,key in [('result.json','result'),('terminal.json','terminal'),('authorization.json','authorization')]:need(pin(out/name)==r[key],'completed batch result/terminal/authorization changed')
 validate(out,r);return r
